{
  "story": "A bill travels from initial proposal through committee review, floor debate, and presidential signature to become law.",
  "aha": {
    "stateId": "sign",
    "observation": "Only after presidential approval or a successful veto override does the bill finally become official law."
  },
  "layout": {
    "preset": "stepper",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "state.active",
        "regions": "variant.regions",
        "values": "state.readouts"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    },
    {
      "id": "prog",
      "kind": "progress",
      "bind": {
        "completedBefore": "inputs.stepIndex"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Legislative Step",
      "options": [
        "Introduce",
        "Committee",
        "Floor Debate",
        "Second Chamber",
        "Conference",
        "Presidential Action"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Restart"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "US Legislative Process",
        "regions": [
          {
            "id": "house",
            "label": "House of Representatives",
            "kind": "chamber"
          },
          {
            "id": "senate",
            "label": "Senate",
            "kind": "chamber"
          },
          {
            "id": "whitehouse",
            "label": "White House",
            "kind": "executive"
          }
        ],
        "states": [
          {
            "id": "intro",
            "label": "Introduction",
            "short": "Step 1",
            "sentence": "A representative introduces the bill.",
            "why": "Bills start their journey in the hopper of either chamber.",
            "active": ["house"],
            "calloutRegion": "house",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Introduction"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "17%"
              }
            ]
          },
          {
            "id": "committee",
            "label": "Committee",
            "short": "Step 2",
            "sentence": "Committees review and amend the bill.",
            "why": "Experts examine details and hold hearings.",
            "active": ["house", "senate"],
            "calloutRegion": "house",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Committee Review"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "33%"
              }
            ]
          },
          {
            "id": "floor",
            "label": "Floor Debate",
            "short": "Step 3",
            "sentence": "The chamber debates and votes on passage.",
            "why": "Amendments are added and final chamber approval is tested.",
            "active": ["house"],
            "calloutRegion": "house",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Floor Vote"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "50%"
              }
            ]
          },
          {
            "id": "second",
            "label": "Second Chamber",
            "short": "Step 4",
            "sentence": "The bill passes through the second chamber.",
            "why": "Both House and Senate must pass identical text.",
            "active": ["senate"],
            "calloutRegion": "senate",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Second Chamber"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "67%"
              }
            ]
          },
          {
            "id": "conf",
            "label": "Conference",
            "short": "Step 5",
            "sentence": "A conference committee reconciles differences.",
            "why": "Resolves discrepancies between House and Senate versions.",
            "active": ["house", "senate"],
            "calloutRegion": "senate",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Conference"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "83%"
              }
            ]
          },
          {
            "id": "sign",
            "label": "Presidential Action",
            "short": "Step 6",
            "sentence": "The President signs the bill into law.",
            "why": "Final executive check completes the legislative enactment.",
            "active": ["whitehouse"],
            "calloutRegion": "whitehouse",
            "readouts": [
              {
                "id": "r1",
                "label": "Stage",
                "value": "Enacted Law"
              },
              {
                "id": "r2",
                "label": "Progress",
                "value": "100%"
              }
            ]
          }
        ]
      }
    ]
  }
}
